@@ -0,0 +1,28 @@
+// Sites: each location belongs to one site, and batches (with their stock,
+// movements and stock-takes) belong to the site of their location.
+import { AppError } from "../errors.js";
+
+/** The site a request uses when it names none. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The site of a location id, or undefined when there is no such location. */
+export function locationSite(store, locationId) {
+  return store.data.locations.find((l) => l.id === locationId)?.site;
+}
+
+/** True when the batch is stored in a location of `site`. */
+export function inSite(store, batch, site) {
+  return locationSite(store, batch.location) === site;
+}
+
+/** The batches stored in `site`, in file order. */
+export function siteBatches(store, site) {
+  return store.data.batches.filter((b) => inSite(store, b, site));
+}
