+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+async function receiveInAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  return handle({
+    method: "POST",
+    path: `/orders/${order.id}/receive`,
+    headers: annex,
+    body: { lots: [{ lot: "AX-1", expires: null, location: "annex-fridge" }] },
+  });
+}
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "X-Larder-Site": "nope" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+});
+
+test("without the header the site is main", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/batches" });
+  assert.equal(res.body.length, 9);
+  assert.equal((await handle({ path: "/batches", headers: annex })).body.length, 0);
+});
+
+test("stock received in the annex is only seen there", async () => {
+  const { handle } = app();
+  const rec = await receiveInAnnex(handle);
+  assert.equal(rec.status, 200);
+  const batchId = rec.body.batches[0].id;
+  const onion = (headers) => handle({ path: "/items/1", headers }).then((r) => r.body.onHand);
+  assert.equal(await onion(annex), 3);
+  assert.equal(await onion({}), 10);
+  assert.equal((await handle({ path: `/batches/${batchId}` })).body.error.code, "unknown_batch");
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 540);
+});
+
+test("receiving into a location of another site is refused", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "x", expires: null, location: "annex-fridge" }] } });
+  assert.equal(res.body.error.code, "unknown_location");
+});
+
+test("cooking only uses the site's stock", async () => {
+  const { handle } = app();
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(res.status, 409);
+  assert.equal(res.body.error.code, "not_enough_stock");
